import { StepProps, StepsProps } from '@arco-design/web-react';
import { CSSProperties, ReactNode, FC, ComponentProps } from 'react';
import { Form } from '@formily/core';
import { DefaultFormStepDecorator } from './decorator/DefaultFormStepDecorator';

export type ReactiveProps<T> = T | ((formStep: IFormStep) => T);
export type ReactiveReactNode = ReactiveProps<string | ReactNode>;
export type JSXComponent = keyof JSX.IntrinsicElements | React.JSXElementConstructor<any>;

export interface Step {
  name: string | number; // 与 SchemaKey 对齐
}

export type FormStepEnv = {
  form: Form;
  steps: Step[];
  beforeStepChange?: FormStepProps['beforeStepChange'];
  onStepChange?: FormStepProps['onStepChange'];
};

export interface IFormStep {
  connect: (options: {
    form: Form;
    steps: Step[];
    /**
     * 使用模式
     * Schema 或 JSX，默认 Schema
     * @default Schema;
     */
    mode?: 'Schema' | 'JSX';
    beforeStepChange?: FormStepProps['beforeStepChange'];
    onStepChange?: FormStepProps['onStepChange'];
  }) => void;
  /**
   * 使用模式
   * Schema 或 JSX，默认 Schema
   * @default Schema;
   */
  mode?: 'Schema' | 'JSX';
  /**
   * 挂载在 formStep 上的数据
   */
  data?: any;
  form: Form;
  /**
   * 当前步骤，0 为第一步
   */
  // form: Form;
  current: number;
  allowNext: boolean;
  allowBack: boolean;
  setCurrent(key: number): void;
  nextBySkipValidate(): void;
  submit: Form['submit'];
  next(): void;
  back(): void;
  nexting: boolean;
  backing: boolean;
  setNexting(flag: boolean): void;
  setBacking(flag: boolean): void;
}

export interface FormStepProps<DecoratorType extends FC<FormStepDecoratorProps> = typeof DefaultFormStepDecorator> {
  formStep?: IFormStep; // createFormStep 传进来、或者不传时，组件内部创建
  children?: ReactNode;
  onStepChange?: (current: number, formStep: IFormStep) => void;
  /**
   * 是否显示 Arco Steps
   * @default true
   */
  showArcoSteps?: ReactiveProps<boolean>;
  current?: number;
  /**
   * Arco Steps Props
   */
  arcoStepsProps?: ReactiveProps<StepsProps>;
  /**
   * current 支持受控
   */

  className?: string | string[];
  decorator?: [DecoratorType] | [DecoratorType, ComponentProps<DecoratorType>];
  /**
   * prefix 前缀
   */
  prefixCls?: string;
  style?: CSSProperties;
  /**
   * 跳转时 check，用于跳转步骤时 check 能否跳过去
   */
  beforeStepChange?: (formStep: IFormStep, targetStep: number) => Promise<boolean> | boolean;
  onSubmit?: (values: any, formStep: IFormStep) => Promise<any> | void;
  /**
   * 常驻内容，比如全局的字段等
   */
  residentContent?: ReactiveReactNode;
  /**
   * 按钮内容
   */
  buttons?: ReactiveReactNode;
  /**
   * 底部内容
   */
  footer?: ReactiveReactNode;
  /**
   * 顶部内容
   */
  top?: ReactiveReactNode;
  /**
   * 使用模式
   * Schema 或 JSX，默认 JSX
   * @default JSX;
   */
  mode?: 'Schema' | 'JSX';
}

export interface StepPaneProps extends StepProps {
  /**
   * 每个步骤的标识
   */
  name: string | number;
}

/**
 * FormStep 装饰容器
 * 用于不同 FormStep 场景，只需配置不同的装饰器即可
 * 装饰器内需预留若干 Slot，会由 FormStep 组件传入渲染。
 * 其余样式、布局、内容都可自定义
 */
export interface FormStepDecoratorProps {
  /**
   * 标题
   */
  title?: ReactNode;
  /**
   * Step 上常驻顶部内容
   */
  topSlot?: ReactNode;
  steps?: ReactNode; // 和 Children 必须传一个
  children?: ReactNode;
  /**
   * ArcoSteps 步骤条
   */
  arcoSteps?: ReactNode;
  /**
   * 底部容器内容
   */
  footerSlot?: ReactNode;
  /**
   * Button 内容容器
   */
  buttonsSlot?: ReactNode;
  /**
   * 常驻内容容器
   */
  residentContentSlot?: ReactNode;
  style?: CSSProperties;
  className?: string | string[];
  [key: string]: any;
  prefixCls?: string;
}
